+impl Param {
+    const fn metadata_is_ascii(&self) -> bool {
+        match self {
+            Self::None
+            | Self::MidiIn
+            | Self::MidiMode
+            | Self::MidiOut
+            | Self::MidiNrpn
+            | Self::VoltPerOct => true,
+            Self::i32 { name, .. }
+            | Self::f32 { name, .. }
+            | Self::bool { name }
+            | Self::Curve { name, .. }
+            | Self::Waveform { name, .. }
+            | Self::Color { name, .. }
+            | Self::Range { name, .. }
+            | Self::Note { name, .. }
+            | Self::MidiCc { name }
+            | Self::MidiChannel { name }
+            | Self::MidiNote { name } => name.is_ascii(),
+            Self::Enum { name, variants } => {
+                if !name.is_ascii() {
+                    return false;
+                }
+                let mut index = 0;
+                while index < variants.len() {
+                    if !variants[index].is_ascii() {
+                        return false;
+                    }
+                    index += 1;
+                }
+                true
+            }
+        }
+    }
+}
